package com.interview.ood.q127_vehicle_fleet_rental.solution;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Objects;

// Record: immutable value object. equals/hashCode/toString generated by the compiler.
// Immutability matters here: multiply() and add() return a new Money — no risk of
// mutating a quote mid-calculation or sharing a mutable amount across two callers.
//
// Why not just BigDecimal? Currency is part of the value identity.
// £150.00 and $150.00 are not the same — add() guards this at runtime.
//
// multiply() always rounds to 2dp with HALF_UP:
// Prevents scale creep. Without setScale, 80 × 7 × 0.85 can accumulate extra decimal
// places, and subsequent comparisons with expected 2dp values fail unexpectedly.
// HALF_UP is the standard rounding mode for financial calculations (ISO 31-0, GAAP).
//
// NOT TO DO: new BigDecimal(dailyRate * days) — the double multiplication
// is already imprecise; BigDecimal wraps the already-corrupted result.
public record Money(BigDecimal amount, String currency) {

    public Money {
        Objects.requireNonNull(amount,   "amount must not be null");
        Objects.requireNonNull(currency, "currency must not be null");
    }

    public Money multiply(BigDecimal factor) {
        return new Money(
            amount.multiply(factor).setScale(2, RoundingMode.HALF_UP),
            currency
        );
    }

    public Money add(Money other) {
        if (!currency.equals(other.currency)) {
            throw new IllegalArgumentException(
                "Cannot add " + currency + " and " + other.currency);
        }
        return new Money(
            amount.add(other.amount).setScale(2, RoundingMode.HALF_UP),
            currency
        );
    }

    // Delegates to BigDecimal.compareTo — scale-independent numeric comparison.
    // BigDecimal.equals() is scale-sensitive: 150.00 and 150.0 are equal numerically
    // but NOT by equals(). Tests must use assertEquals(0, actual.compareTo(expected)),
    // not assertEquals(new BigDecimal("150.00"), actual.amount()).
    public int compareTo(Money other) {
        if (!currency.equals(other.currency)) {
            throw new IllegalArgumentException(
                "Cannot compare " + currency + " and " + other.currency);
        }
        return amount.compareTo(other.amount);
    }
}
